def write_batch(ids, P, label):
    assert set(ids) <= set(P), (label, set(ids) - set(P))
    os.makedirs(OUT, exist_ok=True)
    n = 0
    for cid in ids:
        d = P[cid]
        rec = {"case_id": cid, "prediction_text": d["pred"], "basis": d["basis"],
               "confidence": d["conf"], "trigger": T(d["ly"])}
        with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
        n += 1
    print(label, "written", n)
    return n

_n1 = write_batch(B01, P, "B01")
assert _n1 == 20, _n1
