trig = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
total_bytes = 0
for cid in ALL:
    pth = os.path.join(OUT, cid + ".json")
    with open(pth, encoding="utf-8") as f:
        rec = json.load(f)
    assert rec["case_id"] == cid
    for k in ("prediction_text", "basis", "confidence", "trigger"):
        assert k in rec, (cid, k)
    assert 0.0 <= rec["confidence"] <= 1.0
    t = rec["trigger"]
    for k in ("changed_main", "reserve_used", "disputed", "reason"):
        assert k in t, (cid, k)
    for k in trig:
        if t[k]:
            trig[k] += 1
    total_bytes += os.path.getsize(pth)
print("VERIFY_OK files=40 bytes=", total_bytes)
print("TRIGGER_COUNTS", json.dumps(trig))
print("LIUYAO_IDS", [c for c in ALL if c.startswith("BQ-") and c != "BQ-001"])
